    \includegraphics[width=0.6\textwidth]{figures/3.5aut.png}
    \caption{The overview of AuT. Consuming 40 million hours of supervised data especially more multilingual data, AuT encoder in \method obtain stronger general purpose audio representation in 6.25Hz.}
    \label{fig:aut}
\end{figure}

